    expect("footer not in this plan", old.some((l) => l.includes("A-9 = (not in this plan)")) && old.some((l) => l.includes("A99 = (not in this plan)")), old.join(" | "));
    // a 108-column name and entries wider than one line: every line ≤ 120 and every break at a ` · ` separator
    const wide = plan("w", { items: `- [ ] D1 · **${"\u{1F600}".repeat(12)}** a · test: t1\n` + Array.from({ length: 30 }, (_, k) => `- [ ] D${k + 2} · **Item number ${k + 2}** b · test: t${k + 2}`).join("\n"), baseline: Array.from({ length: 31 }, (_, k) => `- [ ] D${k + 1} · ${k ? "b" : "a"} · test: t${k + 1}`).join("\n") });
    const wd = store(withReviews({ "w.md": wide }));
    const wl = namesFooter(Array.from({ length: 31 }, (_, k) => `D${k + 1}`).join(" "), checkIn(wd).plan("w"));
    const wn = wl.slice(1);
    const rebuilt = wn.map((l, j) => (j ? l.replace(/^ {4}/, "") : l.replace(/^names: /, ""))).join(" · ");
    const expected = Array.from({ length: 31 }, (_, k) => `D${k + 1} = ${k ? `Item number ${k + 1}` : "<U+1F600>".repeat(12)}`).join(" · ");
    expect("footer width", wn.length > 3 && wl.every((l) => l.length <= 120) && rebuilt === expected, wl.join(" | "));
