      const bd = store(withReviews({ "g.md": plan("g"), "h.md": plan("h", { fm: { status: "ready" }, log: "" }).replace("- 2026-09-15 · status → in-progress · start\n", "") }));
      const vb = node([PINNED_CHECKER, "--dir", bd, "--brief"]).stdout.trim(), nb = cli(bd, "--brief").out.trim();
