  const TD = `- [ ] D1 · **Export CSV** Export downloads as CSV · test: export.test.ts\n- [ ] D2 · **Lint** Lint passes · cmd: npm run lint → 0 errors`;
  const today = (() => { const x = new Date(); return `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, "0")}-${String(x.getDate()).padStart(2, "0")}`; })();
  const NOTE = `- ${today} · note · ${MESSAGES_READABILITY.note}`;
  const mstore = (o = {}, slug = "m") => store(withReviews({ [`${slug}.md`]: plan(slug, { items: TD, baseline: ITEMS, ...o }) }));
  const migOuts = []; // every migrate output, for the leak scan at the end
  const mig = (d, ...a) => { const r = cli(d, "--migrate", ...a); migOuts.push(r.out, r.err); return r; };
  const one1 = (r) => r.code === 1 && r.out === "" && r.err.split("\n").length === 1;
