    const lines = ["migrate m: dod: 2", "migrate m: - see `A-9` and S-1", "migrate m: - S-1 · validated · Users are authenticated · source: src/auth.ts", `migrate m: ${NOTE}`];
    const order = (t) => t.split("\n");
    const fwdLines = order(fwd.out);
    const ordered = fwdLines.length === 4 && fwdLines[0] === lines[0] && new Set(fwdLines).size === 4 && lines.every((l) => fwdLines.includes(l)) && fwdLines.at(-1) === lines[3];
    expect("migrate forward", fwd.code === 0 && after === expected && ordered && dry.out === fwd.out && checkIn(d).get("m").problems.length === 0, JSON.stringify({ out: fwd.out, err: fwd.err, same: after === expected }));
    const sn = JSON.parse(snapshot(d)), s0 = JSON.parse(snap0);
    expect("migrate forward writes only the plan", Object.keys(s0).every((k) => k === "m.md" ? sn[k] !== s0[k] : sn[k] === s0[k]) && Object.keys(sn).length === Object.keys(s0).length, JSON.stringify(Object.keys(sn)));
