    expect("migrate already-2", one1(again) && again.err === fmtR("already", { slug: "m", n: 2 }) && snapshot(d) === snap1, again.err);
    const back = mig(d, "--to", "1", "m");
    const untitled = before.replace(TD, ITEMS);
    expect("migrate back", back.code === 0 && readFileSync(file, "utf8") === untitled, back.err + back.out);
    const snap2 = snapshot(d);
