    const d = store(withReviews({ "m.md": plan("m", { items: TD, baseline: ITEMS }).replace("## Assumptions\n- A-1 · validated · Users are authenticated · source: src/auth.ts\n", "## Assumptions\n") }));
    const r = mig(d, "m");
    expect("migrate no-assumption", r.code === 0 && r.out === ["migrate m: dod: 2", `migrate m: ${NOTE}`, fmtR("noAssumptions", { slug: "m" })].join("\n"), r.out);
