    const d = mstore();
    const rel = (x) => relative(process.cwd(), x).split(sep).join("/") || ".";
    refusal("no-plan", d, ["nope"], fmtR("noPlan", { slug: "nope", dir: rel(d) }));
    refusal("bad-slug", d, ["../m"], fmtR("noPlan", { slug: "../m", dir: rel(d) }));
    refusal("untitled", mstore({ items: ITEMS }), ["m"], fmtR("untitledRefusal", { slug: "m", ids: "D1, D2" }));
    refusal("check-problems", mstore({ fm: { status: "bogus" } }), ["m"], fmtR("checkProblems", { slug: "m" }));
    const sColl = (o = {}) => store(withReviews({ "m.md": plan("m", { items: TD, baseline: ITEMS, ...o }).replace("- A-1 · validated", "- S-1 · validated") }));
    refusal("s-collision", sColl(), ["m"], fmtR("sCollision", { slug: "m", n: 1 }));
