    refusal("order already-2 over check-problems", mstore({ fm: { dod: "2", status: "bogus" } }), ["m"], fmtR("already", { slug: "m", n: 2 }));
    refusal("order s-collision over untitled", sColl({ items: ITEMS }), ["m"], fmtR("sCollision", { slug: "m", n: 1 }));
    refusal("order s-collision over check-problems", sColl(), ["m"], fmtR("sCollision", { slug: "m", n: 1 }));
