    const rows = [...md.matchAll(/^- (\d+)\.(\d) (⛔ )?(\(rubric 2\) )?/gm)].map((m) => ({ layer: Number(m[1]), id: `${m[1]}.${m[2]}`, gating: !!m[3], r2: !!m[4] }));
